const webhookData = $('Receive Lark Message').item.json.body;
const userText = webhookData.user_text;
const messageId = webhookData.message_id;
const chatId = webhookData.chat_id;
const senderOpenId = webhookData.sender_open_id;

const senderInfo = $('Look Up Sender Info').item.json;
const senderName = senderInfo.data?.user?.name || 'Unknown user';

const now = new Date();
// Your UTC offset in hours (0 = UTC). Change this to match your team's timezone.
const UTC_OFFSET_HOURS = 0;
const localTime = new Date(now.getTime() + UTC_OFFSET_HOURS * 60 * 60 * 1000 + now.getTimezoneOffset() * 60 * 1000);
const nowLocalStr = localTime.toISOString().replace('T', ' ').substring(0, 19);
const nowTimestamp = now.getTime();

const fieldsResponse = $input.item.json;
const fields = fieldsResponse.data?.items || [];

const readonlyTypes = [1001, 1002, 1003, 1004, 1005, 19, 20];

const typeMap = {
  1: 'Text', 2: 'Number', 3: 'Single select', 4: 'Multi select',
  5: 'Date/time', 7: 'Checkbox', 11: 'Person', 13: 'Phone',
  15: 'URL', 17: 'Attachment', 18: 'One-way link', 21: 'Two-way link',
  22: 'Location', 23: 'Group'
};

const personFieldNames = fields.filter(f => f.type === 11).map(f => f.field_name);
const dateFieldNames = fields.filter(f => f.type === 5).map(f => f.field_name);

const writableFields = fields.filter(f => !readonlyTypes.includes(f.type));

const fieldsDescription = writableFields.map(f => {
  const typeName = typeMap[f.type] || `Unknown (${f.type})`;
  let desc = `- ${f.field_name} (type: ${typeName})`;
  if (f.type === 11) {
    desc += ` [current requester: ${senderName}]`;
  }
  if (f.type === 5) {
    desc += ` [if the user mentions no date, default to the current time: ${nowLocalStr}, timestamp: ${nowTimestamp}]`;
  }
  if (f.description?.text) desc += ` [description: ${f.description.text}]`;
  if (f.property?.options?.length > 0) {
    desc += ` [options: ${f.property.options.map(o => o.name).join(', ')}]`;
  }
  return desc;
}).join('\n');

const fieldNameList = writableFields.map(f => f.field_name).join(', ');

const prompt = `You fill in records for a Lark Base (Bitable) table. From the user's request, generate field values for one new record.

[Requester] ${senderName}
[Current time (UTC${UTC_OFFSET_HOURS >= 0 ? '+' : ''}${UTC_OFFSET_HOURS})] ${nowLocalStr}
[Current Unix timestamp (ms)] ${nowTimestamp}

[User request]
${userText}

[Writable fields]
${fieldsDescription}

[Output rules]
1. Return a valid JSON object: keys are field names, values are the field values
2. Only fill fields you can reasonably infer from the request; leave out any field you cannot infer
3. Text fields: a plain string
4. Single-select fields: exactly one of the listed options, as a string
5. Multi-select fields: an array of strings, each one of the listed options
6. Number fields: a number
7. Date/time fields: a Unix timestamp in milliseconds (number only). If the request mentions no date, use the current timestamp ${nowTimestamp} for every date/time field
8. Checkbox fields: true or false
9. Person fields: the string "SENDER" (the workflow replaces it with the real user ID)
10. Writable field names: ${fieldNameList}
11. Do not fill the field named "AI PRD"; another step fills it automatically

[Important] Output only the JSON object, with no other text, explanation or markdown.`;

return {
  userText,
  prompt,
  message_id: messageId,
  chat_id: chatId,
  sender_open_id: senderOpenId,
  sender_name: senderName,
  person_field_names: personFieldNames,
  date_field_names: dateFieldNames,
  now_timestamp: nowTimestamp,
  tenant_access_token: $('Get Lark Tenant Token').item.json.tenant_access_token
};

const aiContent = $json.choices?.[0]?.message?.content || '';

const jsonMatch = aiContent.match(/\{[\s\S]*\}/);
if (!jsonMatch) {
  throw new Error('No JSON object found in the AI response: ' + aiContent);
}

const recordFields = JSON.parse(jsonMatch[0]);

const prevData = $('Build AI Prompt').item.json;
const senderOpenId = prevData.sender_open_id;
const personFieldNames = prevData.person_field_names || [];
const dateFieldNames = prevData.date_field_names || [];
const nowTimestamp = prevData.now_timestamp;

for (const [key, value] of Object.entries(recordFields)) {
  if (personFieldNames.includes(key) && (!Array.isArray(value) || !value[0]?.id)) {
    recordFields[key] = [{ id: senderOpenId }];
  }
}

for (const [key, value] of Object.entries(recordFields)) {
  if (dateFieldNames.includes(key)) {
    const num = Number(value);
    if (!Number.isFinite(num) || num < 0) {
      recordFields[key] = nowTimestamp;
    } else {
      recordFields[key] = num;
    }
  }
}

return {
  recordFields,
  message_id: prevData.message_id,
  chat_id: prevData.chat_id,
  userText: prevData.userText,
  sender_name: prevData.sender_name,
  tenant_access_token: prevData.tenant_access_token
};

const prdContent = $json.choices?.[0]?.message?.content || '';

const prevData = $('Parse Form Result & Inject Assignees').item.json;
const recordFields = { ...prevData.recordFields };

recordFields['AI PRD'] = prdContent;

return {
  recordFields,
  prdContent,
  message_id: prevData.message_id,
  chat_id: prevData.chat_id,
  userText: prevData.userText,
  sender_name: prevData.sender_name,
  tenant_access_token: prevData.tenant_access_token
};

const prevData = $('Merge PRD into Record Fields').item.json;
const createResult = $json;

const recordId = createResult.data?.record?.record_id || 'Unknown';
const recordFields = prevData.recordFields;
const senderName = prevData.sender_name;

const bitableUrl = '{{BITABLE_BASE_URL}}{{BITABLE_APP_TOKEN}}?table={{BITABLE_TABLE_ID}}&view=veweQZFzEq';

// Format a timestamp as a readable date. Set UTC_OFFSET_HOURS to your timezone (0 = UTC).
const UTC_OFFSET_HOURS = 0;
function formatTimestamp(ts) {
  if (!ts || isNaN(Number(ts))) return String(ts);
  const d = new Date(Number(ts));
  const offset = UTC_OFFSET_HOURS * 60 * 60 * 1000;
  const cst = new Date(d.getTime() + offset + d.getTimezoneOffset() * 60 * 1000);
  return cst.toISOString().replace('T', ' ').substring(0, 10);
}

// Department info
const deptRaw = recordFields['Requester.Department'];
let deptDisplay = '';
if (Array.isArray(deptRaw) && deptRaw.length > 0) {
  deptDisplay = deptRaw.join(', ');
} else if (typeof deptRaw === 'string' && deptRaw) {
  deptDisplay = deptRaw;
}

// Fields to skip (the AI PRD; department is shown separately)
const skipFields = ['AI PRD', 'Requester.Department'];

// Field-name keywords that mark date fields
const dateKeywords = ['Date', 'Time'];

// Build the fields array (two-column layout)
const fieldEntries = [];
for (const [key, value] of Object.entries(recordFields)) {
  if (skipFields.includes(key)) continue;
  let displayValue;
  if (Array.isArray(value) && value[0]?.id) {
    displayValue = senderName;
  } else if (typeof value === 'number' && dateKeywords.some(k => key.includes(k))) {
    displayValue = formatTimestamp(value);
  } else if (typeof value === 'object') {
    displayValue = JSON.stringify(value);
  } else {
    displayValue = String(value);
  }
  fieldEntries.push({ key, displayValue });
}

// Two fields per row
const fieldDivs = [];
for (let i = 0; i < fieldEntries.length; i += 2) {
  const left = fieldEntries[i];
  const right = fieldEntries[i + 1];
  const fields = [
    { is_short: true, text: { tag: 'lark_md', content: '**' + left.key + '**\n' + left.displayValue } }
  ];
  if (right) {
    fields.push({ is_short: true, text: { tag: 'lark_md', content: '**' + right.key + '**\n' + right.displayValue } });
  }
  fieldDivs.push({ tag: 'div', fields });
}

// Top note element: department
const noteElements = deptDisplay
  ? [{ tag: 'note', elements: [{ tag: 'plain_text', content: '🏢 Department: ' + deptDisplay }] }]
  : [];

const cardContent = {
  config: { wide_screen_mode: true },
  header: {
    title: { tag: 'plain_text', content: '✅ Requirement record created' },
    template: 'green'
  },
  elements: [
    {
      tag: 'div',
      fields: [
        { is_short: true, text: { tag: 'lark_md', content: '**Requester**\n' + senderName } },
        { is_short: true, text: { tag: 'lark_md', content: '**Record ID**\n' + recordId } }
      ]
    },
    ...noteElements,
    { tag: 'hr' },
    {
      tag: 'div',
      text: { tag: 'lark_md', content: '**📋 Requirement fields**' }
    },
    ...fieldDivs,
    { tag: 'hr' },
    {
      tag: 'div',
      text: { tag: 'lark_md', content: '**🤖 AI PRD**\nA full PRD was generated from your request and written to the AI PRD field.' }
    },
    { tag: 'hr' },
    {
      tag: 'action',
      actions: [
        {
          tag: 'button',
          text: { tag: 'plain_text', content: '📊 Open in Base' },
          type: 'primary',
          url: bitableUrl
        }
      ]
    }
  ]
};

return {
  message_id: prevData.message_id,
  cardContent: JSON.stringify(cardContent),
  tenant_access_token: prevData.tenant_access_token
};
